    public boolean equals(Object obj) {
        if(obj == this) 
            return true;
        if(!(obj instanceof GrammaticalTermMapImpl)) 
            return false;

        GrammaticalTermMapImpl<T> other = (GrammaticalTermMapImpl<T>)obj;
        return isSkinny == other.isSkinny && map.equals(other.map);
    }

