    public int hashCode() {
        return map.hashCode() + (isSkinny ? 37 : 0);
    }

    @Override
    public boolean isSkinny() {
        return isSkinny;
    }

    @Override
    public GrammaticalTermMap<T> makeSkinny() {
        return new GrammaticalTermMapImpl<T>(map, true);
    }

